from pathlib import Path
import json,html,sys,importlib.metadata as md
import numpy as np,pandas as pd
ROOT=Path(r'D:\Masters\greece_deployment_features_20261022')
scored=pd.read_csv(ROOT/'data/scored_pixels.csv');fit=pd.read_csv(ROOT/'data/scene_fit_metrics.csv');metrics=pd.read_csv(ROOT/'data/validation_metrics.csv');env=pd.read_csv(ROOT/'environment/scene_environment.csv');audit=pd.read_csv(ROOT/'environment/environment_sampling_audit.csv');cal=pd.read_csv(ROOT/'data/water_calibrated_validation.csv');meta=json.loads((ROOT/'models/model_metadata.json').read_text());rank=pd.read_csv(ROOT/'data/exploratory_feature_rankings.csv')
labels={'20210626T161500':'26 Jun 2021, 16:15 UTC','20210702T161544':'02 Jul 2021, 16:15 UTC','20240629T041520':'29 Jun 2024, 04:15 UTC','20240705T160746':'05 Jul 2024, 16:07 UTC'}
table=[]
for sid,g in scored.groupby('scene'):
 f=fit[fit.scene==sid].iloc[0];m=metrics[(metrics.scene==sid)&(metrics.model=='SAR_engineered')&(metrics.scheme=='leave_scene_out')&(metrics.water_subset=='all')].iloc[0]
 table.append({'Acquisition UTC':labels[sid],'Deployment pixels':sum(g.label=='deployment'),'Water pixels':sum(g.label=='water'),'Scene-fit AUC':round(f.scene_fit_AUC_all_water,3),'Scene-fit AUC vs nearer water':round(f.scene_fit_AUC_nearer_water2_4,3),'Held-out AUC':round(m.roc_auc,3)})
table=pd.DataFrame(table)
summary='The supplied deployment footprints can be made more distinct from the labelled water using scene-specific combinations of SAR features. Separation is strongest on 29 June 2024. A single transferable signature has not been established: leaving each acquisition out gives inconsistent results, and adding the coarse environmental interactions did not improve the average held-out ranking.'
method='Ten original SAR layers were extracted for every intersecting label pixel, with coverage fractions and polygon summaries. The main analysis uses pixels with at least 50% footprint coverage and valid values in all ten layers. This yields 58 deployment pixels and 4,487 water pixels across four acquisitions. The footprints represent known deployments; their SAR pixels can include water and mixed scattering. The same four 2021 water footprints are reused in 2024 as background assumptions.'
feature_rows=[('Original SAR','VV, VH, Refined Lee VV (linear and dB); VV GLCM mean, std and entropy; dual-pol H, A and alpha','All ten input layers retained in the pixel and polygon tables. Nine nonduplicate model inputs use VV/VH in dB and the original stored texture/decomposition units.'),('Polarization','VH dB - VV dB; (VV - VH)/(VV + VH)','Contrast and relative polarization power; no arbitrary target-band thresholds.'),('Texture and scattering interactions','H x alpha/90; (1-H) x A; VV dB - filtered VV dB','Exploratory numeric interactions. These do not establish plastic-specific scattering mechanisms.'),('Local contrasts','VV, VH and filtered VV minus an 11 x 11 pixel median ring, excluding the central 5 x 5','Uses local image context without a deployment mask. Neighbouring pixels and texture windows are correlated.'),('Environmental interactions','Wind x VV local contrast; wind x polarization ratio; wave height x filtered contrast; wave height x H; current speed x ratio; temperature x H; chlorophyll x VH local contrast','Products of standardized SAR features and standardized scene context. Seven explicit index bands and a combined held-out model are saved.'),('PCA','Three standardized principal components of the nine base inputs','Fitted without class labels to the supplied reference sample pool. PC1 explains %.1f%%, PC2 %.1f%% and PC3 %.1f%%. PCA maximizes variance, not deployment separation.'%tuple(100*x for x in meta['PCA_explained_variance_ratio'])),('Hyperplanes','Regularized logistic regression; automatic-shrinkage linear discriminant analysis','Scene-specific fits are exploratory. Held-out models use training-only scaling. Logistic C=0.1 was fixed, with equal class and polygon weighting.')]
features=pd.DataFrame(feature_rows,columns=['Feature family','Contents','Interpretation'])
envtable=env[['scene','wind_speed_m_s','wave_height_m','wave_period_s','current_speed_m_s','sst_C','chlorophyll_mg_m3']].copy();envtable['scene']=envtable.scene.map(labels);envtable=envtable.rename(columns={'scene':'Acquisition UTC','wind_speed_m_s':'10 m wind (m/s)','wave_height_m':'Wave height (m)','wave_period_s':'Wave period (s)','current_speed_m_s':'Surface current (m/s)','sst_C':'Near-surface temperature (C)','chlorophyll_mg_m3':'Chlorophyll (mg/m3)'})
validation=metrics[(metrics.water_subset=='all')].groupby(['model','scheme']).roc_auc.mean().unstack();validation.index=validation.index.str.replace('SAR_','').str.replace('_',' ')
rankrows=[]
for sid,g in rank.groupby('scene'):
 for _,r in g.nlargest(3,'descriptive_separation').iterrows():rankrows.append({'Acquisition':labels[sid],'Feature':r.feature,'Direction':r.direction,'Descriptive AUC':round(r.descriptive_separation,3)})
ranktable=pd.DataFrame(rankrows)
caldisplay=cal[['scheme','scene','roc_auc']].copy();caldisplay['scene']=caldisplay.scene.map(labels)
links=[('Greece_2021_feature_analysis.qgz','Open the 2021 QGIS analysis project'),('Greece_2024_feature_analysis.qgz','Open the 2024 QGIS analysis project'),('data/sampled_SAR_pixels.gpkg','Pixel geometries and all sampled values'),('data/all_intersecting_pixels.csv','All intersecting pixels, including boundaries'),('data/polygon_feature_summary.csv','Area-weighted feature summaries per footprint'),('environment/scene_environment.csv','Environmental context per acquisition'),('environment/pixel_environment_samples.csv','Environmental samples: native nearest and regional nearest-valid'),('environment/environment_sampling_audit.csv','Environmental cell, distance, depth and time audit'),('data/environment_interaction_indices.csv','Seven standardized environmental interaction indices'),('data/validation_metrics.csv','Full held-out metrics by scene and water polygon'),('data/PCA_loadings.csv','PCA feature loadings'),('data/hyperplane_coefficients.csv','Pooled hyperplane coefficients'),('data/derived_raster_index.csv','Derived raster band index'),('data/quality_checks.json','Grid and score verification'),('data/qgis_verification.json','Project reopen verification')]
css='''body{font-family:Segoe UI,Arial,sans-serif;color:#173043;background:#edf3f5;margin:0}main{max-width:1190px;margin:auto;padding:36px;background:white}h1{font-size:34px;margin-bottom:8px}h2{font-size:24px;margin-top:36px}p,li{line-height:1.55}table{border-collapse:collapse;width:100%;font-size:13px;margin:18px 0}th,td{border:1px solid #d4e0e6;padding:9px;text-align:left;vertical-align:top}th{background:#e9f2f6}img{max-width:100%;height:auto}a{color:#087a90}.lead{font-size:19px}.note{padding:16px;background:#fff5dc;border-left:4px solid #e7b44b}.small{font-size:13px;color:#506777}code{overflow-wrap:anywhere}figure{margin:24px 0}figcaption{color:#506777;font-size:13px}'''
parts=[f'<!doctype html><html><head><meta charset="utf-8"><title>Greece deployment feature analysis</title><style>{css}</style></head><body><main>', '<h1>Greece deployment feature analysis</h1><p class="small">2021 and 2024 controlled deployments | Analysis completed 23 October 2026 | Local reproducible outputs</p>',f'<p class="lead">{summary}</p>','<h2>Start in QGIS</h2><ol><li>Open the project for the year you want. It starts at the deployment location with the first scene-fitted hyperplane visible and the deployment outlines in yellow.</li><li>Inside each acquisition, toggle one derived SAR layer at a time. Use <b>scene fit logistic EXPLORATORY</b> to explore the local fit, <b>held out scene logistic</b> to see transfer from other images, and <b>PCA RGB</b> for a multivariate colour view.</li><li>The sample-cell layer is initially hidden. Open its attribute table to inspect extracted values. Native environmental grids and seven SAR x environment interaction layers are grouped separately.</li><li>Open the other acquisition group and switch off the first scene when comparing dates. Red model scores are higher target similarity; they are not calibrated plastic probabilities.</li></ol>', '<p>'+ ' &nbsp; | &nbsp; '.join(f'<a href="{url}">{label}</a>' for url,label in links[:2])+'</p>', '<h2>What the maps show</h2>',table.to_html(index=False,border=0),'<p class="note">Scene-fit AUC uses the same labelled image used to fit the score. It describes visual contrast within these labels. The nearer-water column uses water polygons 2 and 4 and shows how easier, distant water sites can inflate the overall result. Held-out AUC uses the other three acquisitions for model fitting. AUC 0.5 is chance ranking; a useful threshold also needs acceptable recall and false positives. Several transferred thresholds fail despite moderately high ranking AUC.</p>', '<figure><img src="plots/deployment_comparison.png" alt="Four acquisition comparison"><figcaption>Original filtered VV, scene-fitted hyperplane, held-out hyperplane and PCA RGB. Yellow outlines are supplied geometry; the score rasters were computed from SAR features, without coordinates or a footprint mask as model predictors. Land and nearby unlabelled objects are not masked.</figcaption></figure>', '<h2>Extraction and engineered features</h2>',f'<p>{method}</p>',features.to_html(index=False,border=0),'<p>Source SAR grids were retained exactly: approximately 11 m east-west by 14 m north-south at this latitude. Pixel spacing is not resolving power. Original rasters were window-read into a compact area covering all supplied water sites and deployments. GLCM features already use 5 x 5 neighbourhoods. Texture neighbourhoods can include pixels outside a deployment footprint. Their stored mean and standard deviation are quantized texture descriptors, so they were not converted to dB. Stored GLCM entropy includes some negative values in the wider crop and is treated as a numerical source descriptor, not ideal Shannon entropy.</p>', '<h2>Environmental context</h2>',envtable.to_html(index=False,border=0,float_format=lambda x:f'{x:.3f}'), '<p class="note">ERA5 atmospheric wind is a 0.25 degree product; the nearest selected cell centre is 4.85 km away. Mediterranean currents, waves, temperature and chlorophyll have native 1/24 degree grids, approximately 4 km. The nearest valid common marine cell is <b>8.40 km from the deployments</b>; the deployment bay is masked. These are regional contextual conditions, not measurements inside the bay. Coastal missing values remain missing in the native-grid rasters.</p>', '<p>Hourly winds are matched by interpolating reconstructed u/v components. Hourly currents and waves use the bracketing acquisition hours, with circular interpolation for wave direction. Temperature and chlorophyll are same-day daily means at approximately 1.018 m model depth. The column called <code>sst_C</code> is near-surface model potential temperature, not satellite skin SST. Sample tables retain native-nearest values separately from nearest-valid regional values and record distances. Model context is constant across every labelled pixel of a scene, preventing environmental grid location from acting as a spatial classifier. Within an acquisition, each environmental interaction rescales an existing SAR feature; it adds cross-scene context rather than new spatial observations at the deployment scale.</p>', '<h2>Held-out diagnostics</h2>', validation.round(3).to_html(border=0),'<figure><img src="plots/held_out_validation.png" alt="Held-out model performance"></figure>', '<p>All preprocessing for each held-out model is fitted using training scenes only. Features and regularization were fixed; test-scene scores were not flipped or thresholds tuned after viewing results. Leave-year-out tests train on the other year, but use the same geographical locality. The 58 target pixels are strongly correlated, come from only two footprints per year, and do not constitute 58 independent deployment trials. There are only four independent acquisition contexts, so environmental interactions are weakly constrained. Their mean leave-scene-out AUC is %.3f versus %.3f for engineered SAR alone.</p>'%(metrics.query("model=='SAR_environment_interactions' and scheme=='leave_scene_out' and water_subset=='all'").roc_auc.mean(),metrics.query("model=='SAR_engineered' and scheme=='leave_scene_out' and water_subset=='all'").roc_auc.mean()),'<h2>Independent water-calibration check</h2><p>To test whether changing water backgrounds explain poor transfer, water polygons 1 and 3 were reserved for robust scene calibration. They were excluded from model fitting and the reported evaluation, which uses deployment pixels and water polygons 2 and 4. No deployment labels from the held-out scene were used to fit its hyperplane. This experiment did not improve transfer and is retained as a diagnostic, with its own map and metrics. Its evaluation population differs from the all-water table above.</p>',caldisplay.round(3).to_html(index=False,border=0),'<h2>Which individual features look useful?</h2><p>The following rankings are exploratory, computed within the labelled scenes and oriented to their better direction. They were not used to select held-out model inputs. In the 2021 scenes and June 2024, filtered VV and texture are prominent; the July 2024 signal is less consistent.</p>',ranktable.to_html(index=False,border=0),'<figure><img src="plots/PCA_scatter.png" alt="PCA class distributions"></figure>', '<h2>Sampling geography and limits</h2><figure><img src="plots/sampling_geography.png" alt="Water and deployment geometry"></figure><p>The water samples span several kilometres, while deployments occupy one small bay. Wind roughness, shoreline effects, acquisition geometry, structures and background texture can therefore explain some apparent separation. No incidence-angle raster was provided, and no land, ship or infrastructure labels were supplied to test specificity. The June 2024 scene is a morning acquisition and the other scenes are afternoon acquisitions; the current evidence does not support attributing cross-scene changes to one cause. A useful next experiment would add verified nearby water and hard distractors for each acquisition and test additional independent deployment events.</p>', '<h2>Files and reproducibility</h2><ul>'+''.join(f'<li><a href="{url}">{label}</a></li>' for url,label in links)+'</ul>', '<p>Each scene has a ten-band original SAR crop, a 19-band derived-feature raster, and a separate water-calibrated held-out score raster. The derived stack contains PCA 1-3, scene-fitted logistic, held-out logistic, scene-fitted shrinkage LDA, water-relative filtered-VV z score, polarization ratio, three local contrasts, held-out environmental score and seven environmental interaction indices. Band names are embedded in GeoTIFFs and listed in <code>data/derived_raster_index.csv</code>. The original batch projects, source rasters and source shapefiles were not edited.</p>', '<p>Python scripts in this folder reproduce extraction, retrieval, environmental matching, modelling, figures, calibration and QGIS packaging. They currently point to the source paths on this laptop. The isolated Python environment is <code>.venv</code>; QGIS packaging uses the installed QGIS 3.40 Python. Model coefficients, PCA loadings, fitted models, download catalogue metadata and sampling audits are retained. Raster scores were verified against every stored sample score, and all grid transforms match the original SAR grid.</p>', '<h2>Primary sources</h2><ul><li><a href="https://open-meteo.com/en/docs/historical-weather-api">Open-Meteo historical weather / ERA5 documentation</a></li><li><a href="https://data.marine.copernicus.eu/product/MEDSEA_MULTIYEAR_PHY_006_004/description">Copernicus Mediterranean physics reanalysis</a></li><li><a href="https://data.marine.copernicus.eu/product/MEDSEA_MULTIYEAR_WAV_006_012/description">Copernicus Mediterranean waves reanalysis</a></li><li><a href="https://data.marine.copernicus.eu/product/MEDSEA_MULTIYEAR_BGC_006_008/description">Copernicus Mediterranean biogeochemistry reanalysis</a></li><li><a href="https://scikit-learn.org/stable/common_pitfalls.html">Scikit-learn: preprocessing and data leakage</a></li></ul></main></body></html>']
(ROOT/'REPORT.html').write_text('\n'.join(parts),encoding='utf-8')
readme=f'''# Greece controlled-deployment feature analysis\n\n{summary}\n\nOpen REPORT.html for the full illustrated report, then Greece_2021_feature_analysis.qgz or Greece_2024_feature_analysis.qgz in QGIS. Toggle one map at a time. Scene-fitted maps are exploratory; held-out maps show transfer to an acquisition not used to fit that model.\n\n- Extracted 10 SAR layers for 58 core deployment pixels and 4,487 water pixels across four acquisitions. Boundary pixels and coverage fractions are retained separately.\n- Added 8 SAR feature transforms/interactions, PCA, regularized logistic hyperplanes, shrinkage LDA, seven SAR-environment interaction indices and held-out environmental scores.\n- Retrieved environmental layers only: wind, waves, currents, near-surface temperature and chlorophyll. Native marine grids are about 4 km and the nearest valid ocean cell is 8.4 km away. These fields describe regional context.\n- Original data and batch projects were not edited. Outputs retain exact native SAR grids.\n\n## Main results\n\n'''+table.to_string(index=False)+'''\n\nScene-fit AUC describes the same labels used to fit the model and is not independent accuracy. Nearer-water AUC uses water polygons 2 and 4. Cross-scene tests are inconsistent; environmental interactions and independent-water calibration do not establish a stable transferable plastic signature.\n\n## Reproduce\n\nRun the Python scripts with .venv/Scripts/python.exe in this order: extract_sar.py, fetch_wind.py, describe_environment.py, fetch_marine.py, assemble_environment.py, analyse_features.py, water_calibrated_analysis.py, make_figures.py, verify_outputs.py. Then run build_qgis_projects.py using the installed QGIS Python batch launcher. Paths are configured in the scripts. Source downloads reuse the user's existing Copernicus credentials and do not store them in this output folder.\n'''
(ROOT/'README.md').write_text(readme,encoding='utf-8')
packages=['numpy','scipy','scikit-learn','pandas','rasterio','fiona','shapely','pyproj','matplotlib','copernicusmarine','xarray','netCDF4','h5py','click','joblib']
(ROOT/'requirements_recorded.txt').write_text('# Python '+sys.version.split()[0]+'; recorded analysis packages\n'+'\n'.join(f'{x}=={md.version(x)}' for x in packages)+'\n')
print('Wrote REPORT.html, README.md and dependency record')
